    slice.player.x_pos = 27 << 16;
    slice.player.y_pos = 26 << 16;
    slice.player.y_velocity = 0x0001_0000;
    slice.player.on_ground = false;

    slice.apply_floor_collision(Some(&grid), false, false, PLAYER_HALF_WIDTH, true);

