    let mut enemy = test_enemy(EnemyFamily::Ninja, 100 << 16, 200 << 16, 2);
    enemy.ninja_state = NinjaState::Stealth;
    // Player 0x30 px above (within 0x20-0x50 range) and 0x08 px right (within ±0x10)
    let player_x = Some((100 + 0x08) << 16);
