    assert_eq!(frame_1292.character_movement, Some(3));
    assert_eq!(frame_1292.kid_on_ground, Some(false));
    assert_eq!(frame_1293.kid_x_velocity, Some(-0x0002_2C40));
    assert_eq!(frame_1293.character_movement, Some(3));
