#[test]
fn demo_input_decoded_correctly() {
    // 0x48 = bits 6,3 = Left+Right? No: bit 6=A, bit 3=Right → A+Right
    let input = demo::decode_demo_byte(0x48);
    assert!(input.right, "bit 3 = Right");
    assert!(input.a, "bit 6 = A");
    assert!(!input.start, "bit 7 stripped");
    assert!(!input.left);
    assert!(!input.up);
    assert!(!input.down);
}

#[test]
fn demo_byte_bit7_stripped() {
    // 0x88 = bits 7,3 → bit 7 stripped, only bit 3 (Right) remains
    let input = demo::decode_demo_byte(0x88);
    assert!(input.right, "bit 3 = Right");
    assert!(!input.start, "bit 7 should be stripped");
}

#[test]
fn demo_camera_handoff_primes_buffer_for_the_hidden_settle_frame() {
    let mut runtime = NativeRuntime::new(manifest());
    runtime.boot_state = BootState::DemoPlay {
        frame_counter: demo::DEMO_GAMEPLAY_START_FRAME - 1,
        data_index: 118,
        use_demo_2: true,
    };

    let handoff_input = runtime
        .step_demo_input(FrameInput::default(), false)
        .expect("demo playback should continue");
    assert_eq!(
        handoff_input,
        FrameInput::default(),
        "camera hand-off still uses default input on the current frame",
    );
    assert_eq!(
        runtime.demo_buffered_input,
        Some(demo::decode_demo_byte(demo::DEMO_INPUT_DATA_2[118])),
        "ReadJoypad should prime the next frame's controller state",
    );

    let hidden_settle_input = runtime
        .step_demo_input(FrameInput::default(), false)
        .expect("demo playback should continue");
    assert_eq!(
        hidden_settle_input,
        demo::decode_demo_byte(demo::DEMO_INPUT_DATA_2[118]),
        "the hidden settle frame should consume the primed byte",
    );
    if let BootState::DemoPlay { data_index, .. } = runtime.boot_state {
        assert_eq!(
            data_index, 119,
            "the second read should advance to the next byte"
        );
    } else {
        panic!("expected DemoPlay after hidden settle");
    }
}

#[test]
fn demo_transform_entry_freezes_buffer_before_flash_frames_start() {
    let mut runtime = NativeRuntime::new(manifest());
    runtime.boot_state = BootState::DemoPlay {
        frame_counter: demo::DEMO_GAMEPLAY_START_FRAME + 10,
        data_index: 118,
        use_demo_2: true,
    };
    runtime.demo_buffered_input = Some(FrameInput {
        right: true,
        ..FrameInput::default()
    });
    runtime.progression.pending_form = Some(PlayerForm::Cyclone);

    let output = runtime
        .step_demo_input(FrameInput::default(), false)
        .expect("demo playback should continue");
    assert_eq!(
        output,
        FrameInput {
            right: true,
            ..FrameInput::default()
        },
        "the queued transform frame should keep using the previously buffered byte",
    );
    assert_eq!(
        runtime.demo_buffered_input,
        Some(FrameInput {
            right: true,
            ..FrameInput::default()
        }),
        "ReadJoypad should stay frozen until the transform coroutine starts",
    );
    if let BootState::DemoPlay {
        frame_counter,
        data_index,
        ..
    } = runtime.boot_state
    {
        assert_eq!(frame_counter, demo::DEMO_GAMEPLAY_START_FRAME + 10);
        assert_eq!(data_index, 118);
    } else {
        panic!("expected DemoPlay after queued transform frame");
    }
}

#[test]
fn demo_1_timeout_overrun_uses_the_adjacent_rom_bytes() {
    assert_eq!(
        demo::demo_byte(false, demo::DEMO_INPUT_DATA_1.len()),
        0x06,
        "demo 1 should keep reading the raw ROM stream after Demo_InputData1 ends",
    );
    assert_eq!(
        demo::demo_byte(false, demo::DEMO_INPUT_DATA_1.len() + 1),
        0xC4,
        "the next overflow byte should match the ROM byte immediately after Demo_InputData1",
    );
}

fn cached_any_percent_demo_runtime_and_script() -> (NativeRuntime, Vec<u8>) {
    cached_tas_runtime_and_script("kc_any_percent_2024")
}

fn cached_any_percent_published_runtime_and_script() -> (NativeRuntime, Vec<u8>) {
    cached_tas_runtime_and_script("any-percent-published")
}

fn cached_generated_runtime() -> NativeRuntime {
    let repo_root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .expect("repo root");
    let manifest_path = repo_root
        .join(".cache/generated/28b904000b2863b6760531807760b571f1a5fc1d/asset-manifest.json");
    let manifest = kid_data::load_manifest(&manifest_path).expect("load cached manifest");
    let mut runtime = NativeRuntime::with_generated_level_layout(manifest);
    runtime.set_trace_physics(false);
    runtime
}

fn cached_tas_runtime_and_script(scenario_slug: &str) -> (NativeRuntime, Vec<u8>) {
    let repo_root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .expect("repo root");
    let scenario_path = repo_root.join(format!("tests/data/tas/{scenario_slug}/scenario.json"));
    let scenario_raw = fs::read_to_string(scenario_path).expect("read TAS scenario");
    let scenario_json: serde_json::Value =
        serde_json::from_str(&scenario_raw).expect("parse TAS scenario");
    let script: Vec<u8> = scenario_json["script"]
        .as_array()
        .expect("script array")
        .iter()
        .map(|value| value.as_u64().expect("script byte") as u8)
        .collect();

    (cached_generated_runtime(), script)
}

fn death_respawn_level_1_script() -> Vec<u8> {
    let mut script = vec![0u8; 9_001 + 1];
    for &frame in &BOOT_TO_LEVEL_START_FRAMES {
        script[frame] |= 0x80;
    }
    script[462] |= 0x80;
    for slot in &mut script[600..=899] {
        *slot |= 1 << 3;
    }
    for slot in &mut script[900..=1_350] {
        *slot |= (1 << 3) | (1 << 6);
    }
    for frame in (940..=1_350).step_by(24) {
        let jump_end = 1_350.min(frame + 3);
        for slot in &mut script[frame..=jump_end] {
            *slot |= 1 << 4;
        }
    }
    for slot in &mut script[1_351..=3_000] {
        *slot |= 1 << 3;
    }
    for frame in (1_600..=3_000).step_by(28) {
        let jump_end = 3_000.min(frame + 2);
        for slot in &mut script[frame..=jump_end] {
            *slot |= 1 << 4;
        }
    }
    script
}

#[test]
fn death_respawn_level_1_exposes_title_menu_cursor_on_frame_136() {
    let mut runtime = cached_generated_runtime();
    let script = death_respawn_level_1_script();

    let mut frame_130 = None;
    let mut frame_136 = None;
    let mut frame_138 = None;
    for (frame_index, mask) in script.iter().copied().enumerate().take(139) {
        let trace = runtime.step_frame(FrameInput::from_mask(mask));
        match frame_index {
            130 => {
                frame_130 = Some((
                    trace.game_mode,
                    trace.kid_x_pos,
                    trace.kid_y_pos,
                    trace.number_objects,
                    trace.number_gfx_objects,
                ));
            }
            136 => {
                frame_136 = Some((
                    trace.game_mode,
                    trace.kid_x_pos,
                    trace.kid_y_pos,
                    trace.number_objects,
                    trace.number_gfx_objects,
                ));
            }
            138 => {
                frame_138 = Some((
                    trace.game_mode,
                    trace.kid_x_pos,
                    trace.kid_y_pos,
                    trace.number_objects,
                    trace.number_gfx_objects,
                ));
                break;
            }
            _ => {}
        }
    }

    // ASM Obj_TitleMenu `loc_1BAEA` keeps the pre-Start title shell alive
    // with the Sega text and title-menu worker already allocated, so oracle
    // reports 4 objects / 2 gfx slots even before loc_1BB52 spawns the menu
    // cursor sprite.
    assert_eq!(
        frame_130,
        Some((GameMode::TitleScreen, None, None, 4, 2)),
        "frame 130 should still be the pre-cursor title shell from Obj_TitleMenu loc_1BAEA",
    );
    // ASM Obj_TitleMenu `loc_1BB52`: the frame-135 Start edge spawns the menu
    // cursor at `x=$28`, `y=$30` and enters `Title_InputLoop`, so oracle
    // exposes that cursor pose on frame 136.
    assert_eq!(
        frame_136,
        Some((
            GameMode::TitleScreen,
            Some(0x0028_0000),
            Some(0x0030_0000),
            4,
            3,
        )),
        "frame 136 should expose the active title-menu cursor from Obj_TitleMenu loc_1BB52",
    );
    // ASM Obj_TitleMenu `Title_InputLoop`: the frame-137 Start press flips
    // `Game_Mode=$0008` on the following frame while keeping the just-spawned
    // cursor pose intact for the hand-off.
    assert_eq!(
        frame_138,
        Some((
            GameMode::LevelTransition,
            Some(0x0028_0000),
            Some(0x0030_0000),
            4,
            3,
        )),
        "frame 138 should have entered mode $0008 while preserving the title-menu cursor hand-off",
    );
}

#[test]
fn death_respawn_level_1_clears_title_cursor_pose_before_title_shell_counts() {
    let mut runtime = cached_generated_runtime();
    let script = death_respawn_level_1_script();

    let mut frames = BTreeMap::new();
    for (frame_index, mask) in script.iter().copied().enumerate().take(169) {
        let trace = runtime.step_frame(FrameInput::from_mask(mask));
        if (160..=168).contains(&frame_index) {
            frames.insert(frame_index, trace);
        }
    }

    let frame_160 = frames.get(&160).expect("frame 160 trace");
    let frame_161 = frames.get(&161).expect("frame 161 trace");
    let frame_165 = frames.get(&165).expect("frame 165 trace");
    let frame_166 = frames.get(&166).expect("frame 166 trace");
    let frame_168 = frames.get(&168).expect("frame 168 trace");

    // ASM Obj_TitleMenu `Title_InputLoop` hands off to `loc_6E2`, and the
    // oracle-backed mode-$0008 bootstrap keeps the last cursor pose only
    // through frame 160 before the player WRAM view clears on frame 161.
    assert_eq!(frame_160.kid_x_pos, Some(0x0028_0000));
    assert_eq!(frame_160.kid_y_pos, Some(0x0030_0000));
    assert_eq!(frame_161.kid_x_pos, None);
    assert_eq!(frame_161.kid_y_pos, None);

    // ASM `loc_6E2` clears the title shell in stages: the 4-object/3-gfx
    // title shell persists after the cursor pose disappears, then drops to the
    // empty shell on frame 166 and the later 2-object preload on frame 168.
    assert_eq!(frame_165.number_objects, 4);
    assert_eq!(frame_165.number_gfx_objects, 3);
    assert_eq!(frame_166.number_objects, 0);
    assert_eq!(frame_166.number_gfx_objects, 0);
    assert_eq!(frame_168.number_objects, 2);
    assert_eq!(frame_168.number_gfx_objects, 0);
}

